const trigger=$("Auto-Media Trigger").first().json;
const input=trigger.body ?? trigger;
const used=new Set((input.source?.usedUrls||[]).map(x=>String(x).split("?")[0].split("#")[0].replace(/\/+$/,"").toLowerCase()));
const now=Date.now();
const clean=s=>String(s||"").replace(/<[^>]*>/g," ").replace(/\s+/g," ").trim();
const candidates=$input.all().map(i=>{const j=i.json||{};const link=String(j.link||j.guid?.["#text"]||j.guid||"").trim();const ts=Date.parse(j.isoDate||j.pubDate||j.date||j.updated||"");return {title:clean(j.title),link,summary:clean(j.contentSnippet||j.content||j.summary||j.description).slice(0,1600),sourceName:clean(j.creator||j.author||j.source||j.feedTitle||"Unknown"),publishedAt:ts?new Date(ts).toISOString():null,ts};}).filter(x=>x.title&&x.link&&!used.has(x.link.split("?")[0].split("#")[0].replace(/\/+$/,"").toLowerCase())&&(!x.ts||now-x.ts>=-600000));
candidates.sort((a,b)=>(b.ts||0)-(a.ts||0));
if(!candidates[0]) throw new Error("No fresh unused RSS story was found.");
return [{json:candidates[0]}];

